SELECT t.id, t.job_group_id, t.group_name, t.group_desc, t.group_order, t.add_time, t.update_time, (SELECT COUNT(1) FROM xxl_job_info WHERE task_group_id = t.id) as job_count FROM xxl_job_task_group t WHERE t.job_group_id = #{jobGroupId}
AND t.group_name LIKE CONCAT('%', #{groupName}, '%')
ORDER BY t.group_order ASC, t.id ASC LIMIT #{offset}, #{pagesize}

SELECT COUNT(1)
FROM xxl_job_info
WHERE task_group_id = #{taskGroupId}
